package com.hrflow.controller; import com.hrflow.dto.LeaveRequestDto;import com.hrflow.entity.*;import com.hrflow.repository.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*; @RestController @RequestMapping("/api/leaves") @RequiredArgsConstructor public class LeaveController{final LeaveRequestRepository req;final LeaveTypeRepository types;final LeaveBalanceRepository bal;@GetMapping public Object all(@RequestParam(required=false)Long employeeId){return employeeId==null?req.findAll():req.findByEmployeeIdOrderByCreatedAtDesc(employeeId);}@GetMapping("/types")public List<LeaveType> types(){return types.findAll();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER','EMPLOYEE')")public LeaveRequest apply(@Valid@RequestBody LeaveRequestDto d){if(d.endDate().isBefore(d.startDate()))throw new IllegalArgumentException("End date before start date");LeaveRequest x=new LeaveRequest();x.setEmployeeId(d.employeeId());x.setLeaveTypeId(d.leaveTypeId());x.setStartDate(d.startDate());x.setEndDate(d.endDate());x.setReason(d.reason());return req.save(x);}@PutMapping("/{id}/approve")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")public LeaveRequest approve(@PathVariable Long id){LeaveRequest x=req.findById(id).orElseThrow();if(x.getStatus()!=LeaveStatus.PENDING)throw new IllegalStateException("Request already reviewed");x.setStatus(LeaveStatus.APPROVED);x.setReviewedAt(Instant.now());return req.save(x);}@PutMapping("/{id}/reject")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")public LeaveRequest reject(@PathVariable Long id,@RequestParam(required=false)String comment){LeaveRequest x=req.findById(id).orElseThrow();x.setStatus(LeaveStatus.REJECTED);x.setReviewerComment(comment);x.setReviewedAt(Instant.now());return req.save(x);}}
